-- STAGING ONLY 500: exact one-cycle sealed runtime activation for Craig-requested Gmail UIDs 639 and 640.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL statement_timeout='120s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-500-exact-uid639-640-sealed-cycle',0));
DO $g$ DECLARE v_head text;BEGIN SELECT max(version) INTO v_head FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$';IF current_user<>'postgres' OR session_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR v_head IS DISTINCT FROM '20260827049000' OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827049000' AND name='499_importer_readonly_navision_resolver') OR (SELECT count(*) FROM public.pdc_monitor_stage_activation_writers WHERE user_id='69846ef4-a74c-4569-9e35-376cf0837888' AND active AND revoked_at IS NULL)<>1 OR EXISTS(SELECT 1 FROM public.vehicles WHERE stock_number_normalized IN('13000769','13017855')) OR (SELECT count(*) FROM public.navision_backend_records WHERE is_current AND record_status='current' AND canonical_vehicle_id IS NULL AND coalesce(normalized_data->>'stock',normalized_data->>'batch') IN('13000769','13017855'))<>2 THEN RAISE EXCEPTION 'PDC_500_TARGET_HEAD_SCOPE_IDENTITY_OR_CONTAINMENT_MISMATCH' USING errcode='55000';END IF;END $g$;
UPDATE public.monitored_mailboxes SET active=true,test_mode=true,updated_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7',updated_at=clock_timestamp() WHERE mailbox_key='pdc_pmb_email' AND lower(mailbox_address)='pmbcontroller@gmail.com';
UPDATE public.pdc_email_monitor_pilot SET enabled=true,minimum_uid=639,automatic_rule_application=true,automatic_authenticated_jobcards=true,outbound_email_enabled=false,ambiguous_to_review=true,exactly_once_required=true,authorized_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7',authorized_by_email='craig.watson@broometoyota.com.au',authorized_at=clock_timestamp(),updated_at=clock_timestamp() WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd' AND mailbox_key='pdc_pmb_email';
UPDATE public.pdc_email_monitor_status SET running_status='running',gateway_instance_id='pdc-monitor-staging-pmbcontroller-hourly-v1',last_started_at=clock_timestamp(),last_error=null,last_error_code=null,updated_at=clock_timestamp() WHERE singleton;
DO $p$ BEGIN IF (SELECT count(*) FROM public.monitored_mailboxes WHERE mailbox_key='pdc_pmb_email' AND active AND test_mode)<>1 OR (SELECT count(*) FROM public.pdc_email_monitor_pilot WHERE singleton AND enabled AND minimum_uid=639 AND automatic_rule_application AND automatic_authenticated_jobcards AND NOT outbound_email_enabled)<>1 THEN RAISE EXCEPTION 'PDC_500_EXACT_CYCLE_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827050000','500_exact_uid639_640_sealed_cycle',ARRAY['Activate exact isolated staging PMB Controller Importer for one sealed runtime cycle beginning strictly at Gmail UID 639','Expected Stock 13000769 and 13017855 each have one current unlinked Navision source row','Use canonical attachment import and all-operation parity guards','Do not resume recurring cron; outbound email false; immediate containment successor required','Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
